# Extract before -> after mapping from training data
before_to_after = train.groupby("before")["after"].apply(list).to_dict()


# Build most frequent mapping (with tie-breaking by first occurrence)
def get_best_mapping(before_to_after_dict):
    mapping = {}
    for before, afters in before_to_after_dict.items():
        counts = Counter(afters)
        max_count = max(counts.values())
        candidates = [a for a in afters if counts[a] == max_count]
        mapping[before] = candidates[0]
    return mapping


mapping = get_best_mapping(before_to_after)


# Enhanced heuristic normalizer with fractions and ordinals support
def normalize_token(token):
    token = str(token)

    # Plain punctuation
    if re.fullmatch(r'[.,"\'!?;:]', token):
        return token

    # Fractions (e.g., "1/2", "3/4", "1 1/2")
    fraction_pattern = r"^(\d+\s+)?(\d+)/(\d+)$"
    match = re.match(fraction_pattern, token.strip())
    if match:
        try:
            whole = match.group(1)
            num = int(match.group(2))
            den = int(match.group(3))
            if whole:
                whole_num = int(whole.strip())
                if den == 2:
                    return f"{num2words(whole_num)} and {num2words(num)} halves"
                elif den == 3:
                    return f"{num2words(whole_num)} and {num2words(num)} thirds"
                elif den == 4:
                    return f"{num2words(whole_num)} and {num2words(num)} quarters"
                else:
                    return f"{num2words(whole_num)} and {num2words(num)} over {num2words(den)}"
            else:
                if den == 2:
                    return f"{num2words(num)} halves"
                elif den == 3:
                    return f"{num2words(num)} thirds"
                elif den == 4:
                    return f"{num2words(num)} quarters"
                else:
                    return f"{num2words(num)} over {num2words(den)}"
        except:
            return token

    # Ordinals (e.g., "1st", "2nd", "23rd")
    ordinal_pattern = r"^(\d+)(st|nd|rd|th)$"
    match = re.match(ordinal_pattern, token.strip(), re.IGNORECASE)
    if match:
        try:
            num = int(match.group(1))
            suffix = match.group(2).lower()
            return num2words(num, ordinal=True)
        except:
            return token

    # Numbers (integers)
    if re.fullmatch(r"\d+", token):
        try:
            n = int(token)
            return num2words(n) if n < 10**9 else token
        except:
            return token

    # Decimal numbers
    if re.fullmatch(r"\d+\.\d+", token):
        try:
            parts = token.split(".")
            whole = int(parts[0])
            frac = parts[1]
            w = num2words(whole)
            if frac == "0":
                return w
            frac_str = " point " + " ".join(num2words(int(d)) for d in frac)
            return w + frac_str
        except:
            return token

    # Currency ($X.XX)
    if re.match(r"\$?\d+\.?\d*\s?(USD|usd)?", token):
        try:
            clean_token = (
                token.replace("$", "").replace("USD", "").replace("usd", "").strip()
            )
            val = float(clean_token)
            dollars = int(val)
            cents = round((val - dollars) * 100)
            d_str = num2words(dollars) + " dollars"
            if cents == 0:
                return d_str
            return d_str + " " + num2words(cents) + " cents"
        except:
            return token

    # Dates (YYYY-MM-DD or MM/DD/YYYY)
    if re.fullmatch(r"\d{4}-\d{2}-\d{2}", token):
        try:
            y, m, d = map(int, token.split("-"))
            return num2words(y) + " " + num2words(m) + " " + num2words(d)
        except:
            return token
    if re.fullmatch(r"\d{1,2}/\d{1,2}/\d{4}", token):
        try:
            m, d, y = token.split("/")
            return num2words(int(m)) + " " + num2words(int(d)) + " " + num2words(int(y))
        except:
            return token

    # Time HH:MM
    if re.fullmatch(r"\d{1,2}:\d{2}", token):
        try:
            h, m = token.split(":")
            h, m = int(h), int(m)
            if m == 0:
                return num2words(h) + " o'clock"
            elif m < 10:
                return num2words(h) + " oh " + num2words(m)
            else:
                return num2words(h) + " " + num2words(m)
        except:
            return token

    return token


